using System;
using Altinn.App.Api.Extensions;
using Altinn.App.Api.Helpers;
using Altinn.App.Core.Features;
using Altinn.App.logic.Clients;
using Altinn.App.logic.DataProcessing;
using Altinn.App.logic.Instantiation;
using Altinn.App.logic.Validation;
using Altinn.App.Logic.Clients;
using Altinn.App.Logic.Fagsystem;
using Altinn.App.options;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.OpenApi.Models;


void RegisterCustomAppServices(IServiceCollection services, IConfiguration config, IWebHostEnvironment env)
{
    services.AddHttpClient<IPreparatClient, PreparatClient>();
    services.AddTransient<IInstanceDataListProvider, PreparatSearchHitsProvider>();
    services.AddTransient<IDataProcessor, DataProcessor>();
    services.AddTransient<IFormDataValidator, FormDataValidator>();
    services.AddTransient<IInstantiationProcessor, Instantiation>();
    services.AddTransient<IAppOptionsProvider, DoseringsformOptions>();
    services.ConfigureMaskinportenClient("Gfvet-MaskinportenSettings");
    services
        .AddHttpClient <IHprClient, HprClient> ()
        .UseMaskinportenAuthorization("nhn:hpr/extended", "nhn:hpr/basic");
    services.AddHttpClient<IFagsystemVarsler, FagsystemVarsler>();

    // Register your apps custom service implementations here.
}

// ###########################################################################
// # Unless you are sure what you are doing do not change the following code #
// ###########################################################################

WebApplicationBuilder builder = WebApplication.CreateBuilder(args);

ConfigureServices(builder.Services, builder.Configuration);

ConfigureWebHostBuilder(builder.WebHost);

// Add Azure KV provider for TT02 & Prod environments
if (!builder.Environment.IsDevelopment())
{
    builder.AddAzureKeyVaultAsConfigProvider();
}

WebApplication app = builder.Build();

Configure();

app.Run();

void ConfigureServices(IServiceCollection services, IConfiguration config)
{
    services.AddAltinnAppControllersWithViews();

    // Register custom implementations for this application
    RegisterCustomAppServices(services, config, builder.Environment);

    // Register services required to run this as an Altinn application
    services.AddAltinnAppServices(config, builder.Environment);

    // Add Swagger support (Swashbuckle)
    services.AddSwaggerGen(c =>
    {
        c.SwaggerDoc("v1", new OpenApiInfo { Title = "Altinn App Api", Version = "v1" });
        StartupHelper.IncludeXmlComments(c.IncludeXmlComments);
    });
}

void ConfigureWebHostBuilder(IWebHostBuilder builder)
{
    builder.ConfigureAppWebHost(args);
}

void Configure()
    {
    string applicationId = StartupHelper.GetApplicationId();
    if (!string.IsNullOrEmpty(applicationId))
    {
        app.UseSwagger(o => o.RouteTemplate = applicationId + "/swagger/{documentName}/swagger.json");

        app.UseSwaggerUI(c =>
        {
            c.SwaggerEndpoint($"/{applicationId}/swagger/v1/swagger.json", "Altinn App API");
            c.RoutePrefix = applicationId + "/swagger";
        });
    }
    app.UseAltinnAppCommonConfiguration();
}

using System;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Altinn.Platform.Storage.Interface.Models;
using Microsoft.Extensions.Configuration;

namespace Altinn.App.Logic.Fagsystem;

public interface IFagsystemVarsler
{
    /// <summary>
    /// Melder fra til fagsystemet at en søknad er sendt inn, så saksbehandlerne kan hente den.
    /// </summary>
    Task VarsleNySoknad(Instance instance);
}

public class FagsystemVarsler : IFagsystemVarsler
{
    private readonly HttpClient _httpClient;

    public FagsystemVarsler(HttpClient httpClient, IConfiguration configuration)
    {
        _httpClient = httpClient;
        _httpClient.BaseAddress = new Uri(configuration["Fagsystem:BaseUrl"]!);
    }

    public async Task VarsleNySoknad(Instance instance)
    {
        var melding = new { instansId = instance.Id, innsender = instance.InstanceOwner.PersonNumber };
        using var response = await _httpClient.PostAsJsonAsync("api/soknader/varsel", melding);
        response.EnsureSuccessStatusCode();
    }
}

