{"path": "App/logic/AarAppOptionsProvider.cs", "content": "using Altinn.App.Core.Features;
using Altinn.App.Core.Models;

namespace Altinn.App.logic;

public class AarAppOptionsProvider : IAppOptionsProvider
{
    public string Id => "aar";

    public Task<AppOptions> GetAppOptions(string? language, Dictionary<string, string> keyValuePairs)
    {
        int year = DateTime.Today.Year;
        var options = new AppOptions
        {
            Options =
            [
                new AppOption { Value = year.ToString(), Label = year.ToString() },
                new AppOption { Value = (year - 1).ToString(), Label = (year - 1).ToString() },
            ],
        };
        return Task.FromResult(options);
    }
}
"}

