namespace Altinn.App.Logic.Clients;

public interface ITilgangslisteClient
{
    /// <summary>
    /// Om organisasjonen står på tilgangslisten godkjente-apotek i ressursregisteret.
    /// </summary>
    Task<bool> ErGodkjentApotek(string organisasjonsnummer, CancellationToken cancellationToken = default);
}

public class TilgangslisteClient : ITilgangslisteClient
{
    private const string Liste = "access-lists/slv/godkjente-apotek/members";

    private readonly HttpClient _httpClient;

    public TilgangslisteClient(HttpClient httpClient, IConfiguration configuration)
    {
        _httpClient = httpClient;
        _httpClient.BaseAddress = new Uri(configuration["Tilgangsliste:BaseUrl"]);
    }

    public async Task<bool> ErGodkjentApotek(string organisasjonsnummer, CancellationToken cancellationToken = default)
    {
        var medlemmer = await _httpClient.GetFromJsonAsync<Medlemmer>(Liste, cancellationToken);
        return medlemmer?.Data.Any(m =>
            m.Identifiers.TryGetValue("urn:altinn:organization:identifier-no", out var orgnr) && orgnr == organisasjonsnummer
        ) ?? false;
    }

    private sealed record Medlemmer(List<Medlem> Data);

    private sealed record Medlem(Dictionary<string, string> Identifiers);
}

