using System;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Altinn.App.Models;
using Microsoft.Extensions.Configuration;

namespace Altinn.App.clients;

public interface ILokalitetClient
{
    Task<LokalitetDto> HentLokalitet(int lokalitetsnummer);
}

public class LokalitetClient : ILokalitetClient
{
    private readonly HttpClient _httpClient;

    public LokalitetClient(HttpClient httpClient, IConfiguration configuration)
    {
        _httpClient = httpClient;
        _httpClient.BaseAddress = new Uri(configuration["LokalitetApi:BaseUrl"]);
    }

    public async Task<LokalitetDto> HentLokalitet(int lokalitetsnummer)
    {
        using var response = await _httpClient.GetAsync($"sites/{lokalitetsnummer}");
        if (!response.IsSuccessStatusCode)
        {
            return null;
        }

        return await response.Content.ReadFromJsonAsync<LokalitetDto>();
    }
}

